PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS data_sources(source_id TEXT PRIMARY KEY,name TEXT NOT NULL,source_url TEXT,license TEXT,retrieved_at TEXT,feed_start_date TEXT,feed_end_date TEXT,archive_hash TEXT,import_status TEXT NOT NULL,quality_notes TEXT);
CREATE TABLE IF NOT EXISTS agencies(agency_id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT,timezone TEXT,language TEXT,source_id TEXT REFERENCES data_sources(source_id),verification_status TEXT NOT NULL DEFAULT 'unverified');
CREATE INDEX IF NOT EXISTS idx_agencies_source ON agencies(source_id);
CREATE TABLE IF NOT EXISTS metro_station_curations(stop_id TEXT PRIMARY KEY REFERENCES stops(stop_id) ON DELETE CASCADE,operator TEXT,mode TEXT,corridor_id TEXT,corridor_name TEXT,curated_sequence INTEGER,source_url TEXT,verification_status TEXT,notes TEXT);
CREATE TABLE IF NOT EXISTS metro_gate_accessibility(gate_record_id TEXT PRIMARY KEY,source_station_name TEXT NOT NULL,stop_id TEXT REFERENCES stops(stop_id),station_type TEXT,gate_list_as_published TEXT,lift_locations_as_published TEXT,notes TEXT,source_url TEXT,verification_status TEXT);
CREATE INDEX IF NOT EXISTS idx_metro_gates_stop ON metro_gate_accessibility(stop_id);
CREATE TABLE IF NOT EXISTS stops(stop_id TEXT PRIMARY KEY,source_stop_id TEXT NOT NULL,agency_id TEXT REFERENCES agencies(agency_id),parent_station_id TEXT,stop_name TEXT NOT NULL,stop_code TEXT,stop_lat REAL,stop_lon REAL,location_type INTEGER,platform_code TEXT,wheelchair_boarding INTEGER,mode TEXT NOT NULL DEFAULT 'bus',area TEXT,source_id TEXT REFERENCES data_sources(source_id),verification_status TEXT NOT NULL DEFAULT 'unverified');
CREATE INDEX IF NOT EXISTS idx_stops_name ON stops(stop_name);
CREATE INDEX IF NOT EXISTS idx_stops_source ON stops(source_id,source_stop_id);
CREATE TABLE IF NOT EXISTS routes(route_id TEXT PRIMARY KEY,source_route_id TEXT NOT NULL,agency_id TEXT REFERENCES agencies(agency_id),route_short_name TEXT,route_long_name TEXT,route_type INTEGER,route_color TEXT,route_text_color TEXT,mode TEXT NOT NULL DEFAULT 'bus',source_id TEXT REFERENCES data_sources(source_id),verification_status TEXT NOT NULL DEFAULT 'unverified');
CREATE INDEX IF NOT EXISTS idx_routes_source ON routes(source_id);
CREATE TABLE IF NOT EXISTS trips(trip_id TEXT PRIMARY KEY,source_trip_id TEXT NOT NULL,route_id TEXT REFERENCES routes(route_id),service_id TEXT,trip_headsign TEXT,direction_id INTEGER,shape_id TEXT,wheelchair_accessible INTEGER,bikes_allowed INTEGER);
CREATE TABLE IF NOT EXISTS stop_times(trip_id TEXT REFERENCES trips(trip_id) ON DELETE CASCADE,stop_id TEXT REFERENCES stops(stop_id),arrival_time TEXT,departure_time TEXT,stop_sequence INTEGER,pickup_type INTEGER,drop_off_type INTEGER,shape_dist_traveled REAL,PRIMARY KEY(trip_id,stop_sequence));
CREATE TABLE IF NOT EXISTS frequencies(trip_id TEXT REFERENCES trips(trip_id) ON DELETE CASCADE,start_time TEXT NOT NULL,end_time TEXT NOT NULL,headway_secs INTEGER,exact_times INTEGER,PRIMARY KEY(trip_id,start_time));
CREATE INDEX IF NOT EXISTS idx_stoptimes_stop ON stop_times(stop_id,trip_id);
CREATE INDEX IF NOT EXISTS idx_trips_route_service ON trips(route_id,service_id);
CREATE TABLE IF NOT EXISTS calendars(service_id TEXT PRIMARY KEY,monday INTEGER,tuesday INTEGER,wednesday INTEGER,thursday INTEGER,friday INTEGER,saturday INTEGER,sunday INTEGER,start_date TEXT,end_date TEXT,source_id TEXT REFERENCES data_sources(source_id));
CREATE INDEX IF NOT EXISTS idx_calendars_range ON calendars(start_date,end_date);
CREATE TABLE IF NOT EXISTS calendar_dates(service_id TEXT,service_date TEXT,exception_type INTEGER,source_id TEXT REFERENCES data_sources(source_id),PRIMARY KEY(service_id,service_date));
CREATE TABLE IF NOT EXISTS shapes(shape_id TEXT,point_lat REAL,point_lon REAL,sequence INTEGER,dist_traveled REAL,PRIMARY KEY(shape_id,sequence));
CREATE TABLE IF NOT EXISTS transfers(from_stop_id TEXT,to_stop_id TEXT,transfer_type INTEGER,min_transfer_time INTEGER,source_id TEXT,PRIMARY KEY(from_stop_id,to_stop_id));
CREATE TABLE IF NOT EXISTS walking_links(link_id TEXT PRIMARY KEY,from_stop_id TEXT,to_stop_id TEXT,distance_meters REAL,duration_seconds INTEGER,accessibility_status TEXT,source_id TEXT,verification_status TEXT,is_illustrative INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS landmarks(landmark_id TEXT PRIMARY KEY,stop_id TEXT,name TEXT,description TEXT,latitude REAL,longitude REAL,direction_text TEXT,accessibility_status TEXT,source_id TEXT,verification_status TEXT,is_illustrative INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS navigation_steps(step_id TEXT PRIMARY KEY,stop_id TEXT,sequence INTEGER,instruction_text TEXT,instruction_text_gu TEXT,instruction_text_hi TEXT,landmark_id TEXT,source_id TEXT,verification_status TEXT,is_illustrative INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS disruptions(disruption_id TEXT PRIMARY KEY,from_stop_id TEXT,to_stop_id TEXT,route_id TEXT,reason TEXT,is_simulated INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feed_metadata(source_id TEXT PRIMARY KEY REFERENCES data_sources(source_id),feed_version TEXT,raw_files TEXT);
